1	////////////////////////////////////////////////////////////////////////////////
2	//
3	// Filename:	rtl/core/cpuops.v
4	// {{{
5	// Project:	Zip CPU -- a small, lightweight, RISC CPU soft core
6	//
7	// Purpose:	This is the ZipCPU ALU function.  It handles all of the
8	//		instruction opcodes 0-13.  (14-15 are divide opcodes).
9	//
10	//
11	// Creator:	Dan Gisselquist, Ph.D.
12	//		Gisselquist Technology, LLC
13	//
14	////////////////////////////////////////////////////////////////////////////////
15	// }}}
16	// Copyright (C) 2015-2025, Gisselquist Technology, LLC
17	// {{{
18	// This program is free software (firmware): you can redistribute it and/or
19	// modify it under the terms of the GNU General Public License as published
20	// by the Free Software Foundation, either version 3 of the License, or (at
21	// your option) any later version.
22	//
23	// This program is distributed in the hope that it will be useful, but WITHOUT
24	// ANY WARRANTY; without even the implied warranty of MERCHANTIBILITY or
25	// FITNESS FOR A PARTICULAR PURPOSE.  See the GNU General Public License
26	// for more details.
27	//
28	// You should have received a copy of the GNU General Public License along
29	// with this program.  (It's in the $(ROOT)/doc directory.  Run make with no
30	// target there if the PDF file isn't present.)  If not, see
31	// <http://www.gnu.org/licenses/> for a copy.
32	// }}}
33	// License:	GPL, v3, as defined and found on www.gnu.org,
34	// {{{
35	//		http://www.gnu.org/licenses/gpl.html
36	//
37	////////////////////////////////////////////////////////////////////////////////
38	//
39	`default_nettype	none
40	// }}}
41	module	cpuops #(
42			// {{{
43			parameter		OPT_MPY = 3,	// == 0 (no mpy),1-4,36
44			parameter	[0:0]	OPT_SHIFTS = 1'b1,
45			parameter	[0:0]	OPT_LOWPOWER = 1'b1
46			// }}}
47		) (
48			// {{{
49			input	wire		i_clk, i_reset, i_stb,
50			input	wire	[3:0]	i_op,
51			input	wire	[31:0]	i_a, i_b,
52			output	reg	[31:0]	o_c,
53			output	wire	[3:0]	o_f,
54			output	reg		o_valid,
55	`ifdef	VMPY_TB
56			// {{{
57			// Define some wires used to peek at internal values during
58			// simulation.  These are *ONLY* used by the ZipCPU mpy_tb
59			// simulation testbench.  They are *NOT* used during synthesis,
60			// and not intended to be used outside of the ZipCPU setup.
61			//
62			output	wire	[5:0]	OPT_MULTIPLY,
63			output	wire	[31:0]	mpy_a_input, mpy_b_input,
64			output	wire	[63:0]	mpy_output,
65			output	wire	[2:0]	mpy_pipe,
66			// }}}
67	`endif
68			output	wire		o_busy
69			// }}}
70		);
71	
72		// Declarations
73		// {{{
74		wire	[31:0]	w_brev_result;
75		wire	z, n, v, vx;
76		reg	c, pre_sign, set_ovfl, keep_sgn_on_ovfl;
77	
78		wire	[32:0]		w_lsr_result, w_asr_result, w_lsl_result;
79	
80		wire	[63:0]	mpy_result; // Where we dump the multiply result
81		wire	mpyhi;		// Return the high half of the multiply
82		wire	mpybusy;	// The multiply is busy if true
83		wire	mpydone;	// True if we'll be valid on the next clock;
84		wire	this_is_a_multiply_op;
85		reg	r_busy;
86	
87		genvar	k;
88		// }}}
89	
90		// Shift register pre-logic
91		// {{{
92		generate if (OPT_SHIFTS)
93		begin : IMPLEMENT_SHIFTS
94			wire	signed	[32:0]	w_pre_asr_input, w_pre_asr_shifted;
95			assign	w_pre_asr_input = { i_a, 1'b0 };
96			assign	w_pre_asr_shifted = w_pre_asr_input >>> i_b[4:0];
97			assign	w_asr_result = (|i_b[31:5])? {(33){i_a[31]}}
98						: w_pre_asr_shifted;// ASR
99			assign	w_lsr_result = ((|i_b[31:6])||(i_b[5]&&(i_b[4:0]!=0)))? 33'h00
100						:((i_b[5])?{32'h0,i_a[31]}
101	
102						: ( { i_a, 1'b0 } >> (i_b[4:0]) ));// LSR
103			assign	w_lsl_result = ((|i_b[31:6])||(i_b[5]&&(i_b[4:0]!=0)))? 33'h00
104						:((i_b[5])?{i_a[0], 32'h0}
105						: ({1'b0, i_a } << i_b[4:0]));	// LSL
106		end else begin : NO_SHIFTS
107	
108			assign	w_asr_result = {   i_a[31], i_a[31:0] };
109			assign	w_lsr_result = {      1'b0, i_a[31:0] };
110			assign	w_lsl_result = { i_a[31:0],      1'b0 };
111	
112		end endgenerate
113		// }}}
114	
115		//
116		// Bit reversal pre-logic
117		// {{{
118		generate
119		for(k=0; k<32; k=k+1)
120		begin : bit_reversal_cpuop
121			assign w_brev_result[k] = i_b[31-k];
122		end endgenerate
123		// }}}
124	
125		// Prelogic for our flags registers : set_ovfl and keep_sgn_on_ovfl
126		// {{{
127		always @(posedge i_clk)
128		if (i_stb) // 1 LUT
129			set_ovfl<=(((i_op==4'h0)&&(i_a[31] != i_b[31]))//SUB&CMP
130				||((i_op==4'h2)&&(i_a[31] == i_b[31])) // ADD
131				||(i_op == 4'h6) // LSL
132				||(i_op == 4'h5)); // LSR
133	
134		always @(posedge i_clk)
135		if (i_stb) // 1 LUT
136			keep_sgn_on_ovfl<=
137				(((i_op==4'h0)&&(i_a[31] != i_b[31]))//SUB&CMP
138				||((i_op==4'h2)&&(i_a[31] == i_b[31]))); // ADD
139		// }}}
140	
141		////////////////////////////////////////////////////////////////////////
142		//
143		// Multiply handling
144		// {{{
145		////////////////////////////////////////////////////////////////////////
146		//
147		//
148	
149		// A 4-way multiplexer can be done in one 6-LUT.
150		// A 16-way multiplexer can therefore be done in 4x 6-LUT's with
151		//	the Xilinx multiplexer fabric that follows.
152		// Given that we wish to apply this multiplexer approach to 33-bits,
153		// this will cost a minimum of 132 6-LUTs.
154	
155		assign	this_is_a_multiply_op = (i_stb)&&((i_op[3:1]==3'h5)||(i_op[3:0]==4'hc));
156	
157	`ifdef	FORMAL
158	`define	MPYOP	abs_mpy
159	`else
160	`define	MPYOP	mpyop
161	`endif
162		`MPYOP #(
163			// {{{
164			.OPT_MPY(OPT_MPY),
165			.OPT_LOWPOWER(OPT_LOWPOWER)
166			// }}}
167		) thempy(
168			// {{{
169			.i_clk(i_clk), .i_reset(i_reset),
170			.i_stb(this_is_a_multiply_op), .i_op(i_op[1:0]),
171			.i_a(i_a), .i_b(i_b), .o_valid(mpydone),
172			.o_busy(mpybusy), .o_result(mpy_result), .o_hi(mpyhi)
173			// }}}
174		);
175		// }}}
176		////////////////////////////////////////////////////////////////////////
177		//
178		// The master ALU case statement
179		// {{{
180		always @(posedge i_clk)
181		if (i_stb)
182		begin
183			pre_sign <= (i_a[31]);
184			c <= 1'b0;
185			casez(i_op)
186			4'b0000:{c,o_c } <= {1'b0,i_a}-{1'b0,i_b};// CMP/SUB
187			4'b0001:   o_c   <= i_a & i_b;		// BTST/And
188			4'b0010:{c,o_c } <= i_a + i_b;		// Add
189			4'b0011:   o_c   <= i_a | i_b;		// Or
190			4'b0100:   o_c   <= i_a ^ i_b;		// Xor
191			4'b0101:{o_c,c } <= w_lsr_result[32:0];	// LSR
192			4'b0110:{c,o_c } <= w_lsl_result[32:0]; // LSL
193			4'b0111:{o_c,c } <= w_asr_result[32:0];	// ASR
194			4'b1000:   o_c   <= w_brev_result;	// BREV
195			4'b1001:   o_c   <= { i_a[31:16], i_b[15:0] }; // LODILO
196			4'b1010:   o_c   <= mpy_result[63:32];	// MPYHU
197			4'b1011:   o_c   <= mpy_result[63:32];	// MPYHS
198			4'b1100:   o_c   <= mpy_result[31:0];	// MPY
199			default:   o_c   <= i_b;		// MOV, LDI
200			endcase
201		end else if (!OPT_LOWPOWER || mpydone)
202			// set the output based upon the multiply result
203			o_c <= (mpyhi)?mpy_result[63:32]:mpy_result[31:0];
204		// }}}
205	
206		// o_busy, r_busy
207		// {{{
208		initial	r_busy = 1'b0;
209		always @(posedge i_clk)
210		if (i_reset)
211			r_busy <= 1'b0;
212		else if (OPT_MPY > 1)
213			r_busy <= ((i_stb)&&(this_is_a_multiply_op))||mpybusy;
214		else
215			r_busy <= 1'b0;
216	
217		assign	o_busy = (r_busy); // ||((OPT_MPY>1)&&(this_is_a_multiply_op));
218		// }}}
219	
220		// Flags assignment and determination
221		// {{{
222		assign	z = (o_c == 32'h0000);
223		assign	n = (o_c[31]);
224		assign	v = (set_ovfl)&&(pre_sign != o_c[31]);
225		assign	vx = (keep_sgn_on_ovfl)&&(pre_sign != o_c[31]);
226	
227		assign	o_f = { v, n^vx, c, z };
228		// }}}
229	
230		// o_valid
231		// {{{
232		initial	o_valid = 1'b0;
233		always @(posedge i_clk)
234		if (i_reset)
235			o_valid <= 1'b0;
236		else if (OPT_MPY <= 1)
237			o_valid <= (i_stb);
238		else
239			o_valid <=((i_stb)&&(!this_is_a_multiply_op))||(mpydone);
240		// }}}
241	
242	`ifdef	VMPY_TB
243	// {{{
244		assign	OPT_MULTIPLY = OPT_MPY;
245		generate if (OPT_MPY == 0)
246		begin : VGEN0
247			assign	mpy_a_input = 0;
248			assign	mpy_b_input = 0;
249			assign	mpy_pipe = 1'b0;
250		end else if (OPT_MPY == 1)
251		begin : VGEN1
252			assign	mpy_a_input = thempy.IMPY.MPY1CK.w_mpy_a_input[31:0];
253			assign	mpy_b_input = thempy.IMPY.MPY1CK.w_mpy_b_input[31:0];
254			assign	mpy_pipe = 3'b0;
255		end else if (OPT_MPY == 2)
256		begin : VGEN2
257			assign	mpy_a_input = thempy.IMPY.MPN1.MPY2CK.r_mpy_a_input[31:0];
258			assign	mpy_b_input = thempy.IMPY.MPN1.MPY2CK.r_mpy_b_input[31:0];
259			assign	mpy_pipe = { 2'b0, thempy.IMPY.MPN1.MPY2CK.mpypipe };
260		end else if (OPT_MPY == 3)
261		begin : VGEN_NORMAL
262			assign	mpy_a_input = thempy.IMPY.MPN1.MPN2.MPY3CK.r_mpy_a_input;
263			assign	mpy_b_input = thempy.IMPY.MPN1.MPN2.MPY3CK.r_mpy_b_input;
264			assign	mpy_pipe = { 1'b0, thempy.IMPY.MPN1.MPN2.MPY3CK.mpypipe };
265		end else if (OPT_MPY == 4)
266		begin : VGEN_PARTIAL
267			assign	mpy_a_input = thempy.IMPY.MPN1.MPN2.MPN3.MPY4CK.r_mpy_a_input;
268			assign	mpy_b_input = thempy.IMPY.MPN1.MPN2.MPN3.MPY4CK.r_mpy_b_input;
269			assign	mpy_pipe = thempy.IMPY.MPN1.MPN2.MPN3.MPY4CK.mpypipe;
270		end else begin : VGEN_SLOW
271			assign	mpy_a_input = thempy.IMPY.MPN1.MPN2.MPN3.MPYSLOW.slowmpyi.i_a[31:0];
272			assign	mpy_b_input = thempy.IMPY.MPN1.MPN2.MPN3.MPYSLOW.slowmpyi.i_b[31:0];
273			assign	mpy_pipe = {(3){mpybusy}};
274		end endgenerate
275	
276		assign	mpy_output = mpy_result;
277	// }}}
278	`endif
279	////////////////////////////////////////////////////////////////////////////////
280	////////////////////////////////////////////////////////////////////////////////
281	////////////////////////////////////////////////////////////////////////////////
282	//
283	// Formal properties
284	// {{{
285	////////////////////////////////////////////////////////////////////////////////
286	////////////////////////////////////////////////////////////////////////////////
287	////////////////////////////////////////////////////////////////////////////////
288	`ifdef	FORMAL
289		// Declarations
290		// {{{
291		initial	assume(i_reset);
292		reg	f_past_valid;
293	
294		initial	f_past_valid = 1'b0;
295		always @(posedge i_clk)
296			f_past_valid <= 1'b1;
297		// }}}
298	
299	`define	ASSERT	assert
300	`ifdef	CPUOPS
301	`define	ASSUME	assume
302	`else
303	`define	ASSUME	assert
304	`endif
305	
306		// No request should be given us if/while we are busy
307		// {{{
308		always @(posedge i_clk)
309		if (o_busy)
310			`ASSUME(!i_stb);
311		// }}}
312	
313		// Following any request other than a multiply request, we should
314		// respond in the next cycle
315		// {{{
316		always @(posedge i_clk)
317		if ((f_past_valid)&&(!$past(o_busy))&&(!$past(this_is_a_multiply_op)))
318			`ASSERT(!o_busy);
319		// }}}
320	
321		// Valid and busy can never both be asserted
322		// {{{
323		always @(posedge i_clk)
324			`ASSERT((!o_valid)||(!r_busy));
325		// }}}
326	
327		// Following any busy, we should always become valid
328		// {{{
329		always @(posedge i_clk)
330		if ((f_past_valid)&&($past(o_busy))&&(!o_busy))
331			`ASSERT($past(i_reset) || o_valid);
332		// }}}
333	
334		// Check the shift values
335		// {{{
336		always @(posedge i_clk)
337		if ((f_past_valid)&&($past(i_stb)))
338		begin
339			if (($past(|i_b[31:6]))||($past(i_b[5:0])>6'd32))
340			begin
341				assert(($past(i_op)!=4'h5)
342						||({o_c,c}=={(33){1'b0}}));
343				assert(($past(i_op)!=4'h6)
344						||({c,o_c}=={(33){1'b0}}));
345				assert(($past(i_op)!=4'h7)
346						||({o_c,c}=={(33){$past(i_a[31])}}));
347			end else if ($past(i_b[5:0]==6'd32))
348			begin
349				assert(($past(i_op)!=4'h5)
350					||(o_c=={(32){1'b0}}));
351				assert(($past(i_op)!=4'h6)
352					||(o_c=={(32){1'b0}}));
353				assert(($past(i_op)!=4'h7)
354					||(o_c=={(32){$past(i_a[31])}}));
355			end if ($past(i_b)==0)
356			begin
357				assert(($past(i_op)!=4'h5)
358					||({o_c,c}=={$past(i_a), 1'b0}));
359				assert(($past(i_op)!=4'h6)
360					||({c,o_c}=={1'b0, $past(i_a)}));
361				assert(($past(i_op)!=4'h7)
362					||({o_c,c}=={$past(i_a), 1'b0}));
363			end if ($past(i_b)==1)
364			begin
365				assert(($past(i_op)!=4'h5)
366					||({o_c,c}=={1'b0, $past(i_a)}));
367				assert(($past(i_op)!=4'h6)
368					||({c,o_c}=={$past(i_a),1'b0}));
369				assert(($past(i_op)!=4'h7)
370					||({o_c,c}=={$past(i_a[31]),$past(i_a)}));
371			end if ($past(i_b)==2)
372			begin
373				assert(($past(i_op)!=4'h5)
374					||({o_c,c}=={2'b0, $past(i_a[31:1])}));
375				assert(($past(i_op)!=4'h6)
376					||({c,o_c}=={$past(i_a[30:0]),2'b0}));
377				assert(($past(i_op)!=4'h7)
378					||({o_c,c}=={{(2){$past(i_a[31])}},$past(i_a[31:1])}));
379			end if ($past(i_b)==31)
380			begin
381				assert(($past(i_op)!=4'h5)
382					||({o_c,c}=={31'b0, $past(i_a[31:30])}));
383				assert(($past(i_op)!=4'h6)
384					||({c,o_c}=={$past(i_a[1:0]),31'b0}));
385				assert(($past(i_op)!=4'h7)
386					||({o_c,c}=={{(31){$past(i_a[31])}},$past(i_a[31:30])}));
387			end
388		end
389		// }}}
390	`endif
391	// }}}
392	endmodule
393	//
394	// iCE40	NoMPY,w/Shift	NoMPY,w/o Shift
395	//  SB_CARRY		 64		 64
396	//  SB_DFFE		  3		  3
397	//  SB_DFFESR		  1		  1
398	//  SB_DFFSR		 33		 33
399	//  SB_LUT4		748		323
400

